import math
from datetime import datetime, timedelta

GRACE_PERIOD = timedelta(minutes=15)
MAX_REGULAR_DURATION = timedelta(hours=24)
MAX_DURATION_PENALTY = 200.00
SECONDS_PER_HOUR = 3600.0


class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = float(hourly_rate)

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time.")

        duration = exit - entry

        if duration > MAX_REGULAR_DURATION:
            return MAX_DURATION_PENALTY

        if duration <= GRACE_PERIOD:
            return 0.00

        hours_charged = math.ceil(duration.total_seconds() / SECONDS_PER_HOUR)
        return round(hours_charged * self.hourly_rate, 2)
